          "Za produkcję odpowiada Papaya Films. Producentem jest Kacper Sawicki, showrunnerami są Magdalena Ignatowicz-Salska i Jan Dybus, który jest też reżyserem. Zdjęcia robi Barbara Kai Kaniewska.",
